contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single function performing the drive and the assertion
    function runTest(address depositor, uint amt) public {
        // require preconditions: caller must be depositor and deposit amount positive
        require(depositor == address(this), "caller must be depositor");
        require(amt > 0, "amt>0");

        // observe previous balance
        uint before = c.balances(address(this));

        // ensure contract has enough ETH to forward
        require(address(this).balance >= amt, "not enough ETH for deposit");

        // perform the deposit call on c with provided amount
        c.Deposit{value: amt}();

        // read new balance
        uint after = c.balances(address(this));

        // The general rule: depositing exactly MinDeposit increases the balance by amt
        // We express it generally: if amt equals MinDeposit, then after == before + amt
        // Use public getter for MinDeposit
        assert(!(amt == c.MinDeposit() ) || (after == before + amt));
    }

    // allow this test contract to receive ETH for forwarding
    receive() external payable {}
    fallback() external payable {}
}

