contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // record contract balance before the call
        uint before = address(c).balance;
        bool reverted;
        try c.Deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint after = address(c).balance;
        // If amount >= MinDeposit then either the Deposit call should not revert,
        // or if it did revert the contract balance must not have increased by amount.
        // We express this as: amount < MinDeposit OR (not reverted) OR (after - before < amount + 1 and after >= before)
        // Simplify to: if amount >= MinDeposit then (not reverted) OR (after == before)
        // Use observable MinDeposit via c.MinDeposit()
        uint minDep = c.MinDeposit();
        if (amount >= minDep) {
            assert(!reverted || after == before);
        } else {
            // No constraint if amount < MinDeposit; still need a valid assert expression overall
            assert(reverted || after >= before);
        }
    }
    receive() external payable {}
}

