import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz the depositor address and the deposit amount
    function testFuzz_property(address depositor, uint256 amt) public {
        // admissible domain: deposit must be at least MinDeposit and depositor should be non-zero
        vm.assume(depositor != address(0));
        // get MinDeposit from contract
        uint256 min = c.MinDeposit();
        // require amt in a wide range but ensure it's >= min to trigger Deposit behavior
        // if amt < min the Deposit is a no-op in both versions, so we want >= min
        // bound amt to avoid extremely large VM allocations but keep full uint range otherwise
        uint256 amount = amt;
        if (amount < min) {
            // coerce into admissible domain while keeping fuzz influence
            amount = min + (uint256(uint160(depositor)) & ((1 << 128) - 1));
        }

        // fund depositor and record old balance mapping (via getter)
        vm.deal(depositor, amount);
        uint256 before = c.balances(depositor);

        // perform Deposit as depositor
        vm.prank(depositor);
        // call and capture whether it reverted (reference never reverts for valid deposit)
        bool ok;
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful Deposit call on the reference, balances[depositor] == before + amount
        // The single assertion reads the contract's public getter to verify this universal property.
        // If the call reverted, then the property is that balances unchanged (both versions would not change)
        if (ok) {
            assertTrue(c.balances(depositor) == before + amount);
        } else {
            assertTrue(c.balances(depositor) == before);
        }
    }
}

