import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: depositor address and amount to deposit
    function testFuzz_property(address depositor, uint256 amount) public {
        // Keep domain wide but meaningful: amount must be >= MinDeposit to trigger deposit path
        // and not exceed max uint256 (already guaranteed). We also avoid zero address for depositor
        vm.assume(depositor != address(0));

        uint256 Min = c.MinDeposit();

        // Bound amount to a wide range but allow values that can cause overflow when added to existing balance.
        // Keep it wide: up to 2**256-1. Use at least Min so Deposit's if branch executes.
        if (amount < Min) {
            // bump amount into admissible domain without excluding overflow cases
            amount = Min;
        }

        // Arrange: set an initial balance for depositor so that balances + amount might overflow in mutant.
        // We simulate prior deposits by directly manipulating via Deposit from this test using vm.prank.
        // First, ensure depositor has some ether to send
        vm.deal(depositor, amount + 1 ether);

        // Record old balance mapping value
        uint256 oldBal = c.balances(depositor);

        // Act: perform Deposit from depositor
        vm.prank(depositor);
        // call payable Deposit with given amount
        c.Deposit{value: amount}();

        // After Deposit, the correct contract guarantees balances[depositor] == oldBal + amount
        // We assert that property; the mutant (without overflow check) will fail for some inputs where addition wraps
        uint256 newBal = c.balances(depositor);
        assertTrue(newBal == oldBal + amount);
    }
}

