        uint256 min = 1 ether;
        // Bound amount to wide range but ensure it is >= min and does not overflow when added to current balance
        uint256 before = c.balances(depositor);

        // We want the reference to always succeed in performing balances[depositor] + amount without wrap.
        // So we restrict amount to be <= type(uint256).max - before.
