import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: depositor address and amount to deposit
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero (EOA or arbitrary address is fine)
        vm.assume(depositor != address(0));
        // bound amount to a wide range but allow very large values to trigger overflow
        uint256 amt = bound(amount, 0, type(uint256).max);

        // ensure depositor has funds to send
        vm.deal(depositor, amt);

        // record previous balance mapping for depositor
        uint256 before = c.balances(depositor);

        // perform Deposit from depositor with the fuzzed amount
        vm.prank(depositor);
        bool ok;
        try c.Deposit{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant we assert: after Deposit (whether it reverted or not), the reference
        // implementation never makes balances[depositor] smaller than before (no wrap-around)
        // We only assert when the call succeeded (ok==true) and amt >= MinDeposit.
        // Read MinDeposit via public getter
        uint256 minDep = c.MinDeposit();
        if (ok && amt >= minDep) {
            uint256 after = c.balances(depositor);
            // single assertion: after >= before
            assertTrue(after >= before);
        } else {
            // If the call didn't execute (reverted) or amount < MinDeposit, the reference
            // contract still satisfies that balances did not decrease (no state change),
            // so balances == before. We assert that as the same general rule by checking >=.
            uint256 after = c.balances(depositor);
            assertTrue(after >= before);
        }
    }
}

